CREATE OR REPLACE FUNCTION public.finance_regression_tests() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE actor uuid:=auth.uid();party uuid;plan uuid;con uuid;rec uuid;inst uuid;rev uuid;result jsonb;v numeric;rejected boolean; BEGIN IF NOT public.has_role(actor,'admin') THEN RAISE EXCEPTION 'اختبار الأدمن فقط'; END IF; BEGIN SELECT id INTO party FROM public.parties WHERE archived_at IS NULL AND merged_into_id IS NULL LIMIT 1; IF party IS NULL THEN RAISE EXCEPTION 'لا يوجد عميل للاختبار';END IF; plan:=public.save_payment_plan(NULL,'خطة اختبار قابلة للتراجع',3,1,NULL,'اختبار تقسيم الأقساط');con:=public.create_contract(jsonb_build_object('contract_no','TEST-'||gen_random_uuid(),'party_id',party,'start_date',current_date,'end_date',current_date+365,'annual_rent_excl_vat',100,'vat_rate',15,'payment_plan_id',plan,'signed_at',now(),'units',jsonb_build_array(jsonb_build_object('unit_id',(SELECT id FROM public.units WHERE leasing_status='available' AND NOT is_test LIMIT 1),'rent',100))),'اختبار عقد قابل للتراجع');PERFORM public.activate_contract(con,'اختبار تفعيل العقد');PERFORM public.activate_contract(con,'اختبار منع تكرار الأقساط');IF(SELECT count(*) FROM public.installments WHERE contract_id=con)<>3 OR(SELECT sum(amount_incl_vat) FROM public.installments WHERE contract_id=con)<>115 THEN RAISE EXCEPTION 'فشل تطابق الأقساط';END IF;SELECT id INTO inst FROM public.installments WHERE contract_id=con AND sequence_no=1;rec:=public.record_receipt(jsonb_build_object('party_id',party,'contract_id',con,'paid_at',now(),'method','test','amount_excl_vat',33.33,'vat_amount',5,'idempotency_key',gen_random_uuid()),'اختبار إيصال قابل للتراجع');PERFORM public.allocate_receipt(rec,inst,33.33,5,'اختبار تخصيص الدفعة');PERFORM public.verify_receipt(rec,'اختبار تحقق نفس المسجل');IF(SELECT status FROM public.installments WHERE id=inst)<>'paid' THEN RAISE EXCEPTION 'فشل التحقق من القسط';END IF;rev:=public.reverse_receipt(rec,'اختبار عكس الإيصال');IF(SELECT amount_incl_vat FROM public.receipts WHERE id=rev)<>-38.33 OR(SELECT status FROM public.installments WHERE id=inst)='paid' THEN RAISE EXCEPTION 'فشل عكس الدفعة';END IF;rejected:=false;BEGIN PERFORM public.reverse_receipt(rec,'اختبار منع تكرار العكس');EXCEPTION WHEN OTHERS THEN rejected:=true;END;IF NOT rejected THEN RAISE EXCEPTION 'العكس المكرر لم يرفض';END IF;result:=jsonb_build_object('installments_exact',true,'activation_idempotent',true,'same_person_verification',true,'reversal_restores_due',true,'double_reversal_rejected',true);RAISE EXCEPTION 'FINANCE_TEST_ROLLBACK' USING ERRCODE='P0002';EXCEPTION WHEN SQLSTATE 'P0002' THEN RETURN result;END;END $$;
REVOKE ALL ON FUNCTION public.finance_regression_tests() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.finance_regression_tests() TO authenticated;
SELECT exists(SELECT 1 FROM pg_proc WHERE proname='finance_regression_tests') AS rollback_test_available;